const files = {"index.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no\">\n  <title>Tiny Factory Drop</title>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n  <main id=\"app\" class=\"theme-toy\">\n    <section id=\"startScreen\" class=\"start-screen\">\n      <div class=\"start-card\">\n        <div class=\"gear-logo\" aria-hidden=\"true\">TF</div>\n        <p class=\"eyebrow\">Pocket production line</p>\n        <h1>Tiny Factory Drop</h1>\n        <p class=\"start-copy\">Drop scraps, merge better products, ship orders, and unlock tiny factories.</p>\n        <button id=\"playBtn\" class=\"btn btn-primary btn-large\" type=\"button\">Start Factory</button>\n        <button id=\"continueBtn\" class=\"btn btn-soft hidden\" type=\"button\">Continue Save</button>\n        <p class=\"micro\">Works offline. Saves on this browser.</p>\n      </div>\n    </section>\n\n    <section id=\"gameScreen\" class=\"game-screen hidden\">\n      <header class=\"topbar\">\n        <div class=\"brand\">\n          <span class=\"brand-mark\" aria-hidden=\"true\">TF</span>\n          <span>Tiny Factory</span>\n          <b id=\"factoryName\">Toy Factory</b>\n        </div>\n        <div class=\"wallet\">\n          <button id=\"tokenShopBtn\" class=\"wallet-chip\" type=\"button\" aria-label=\"Open Factory Token shop\">Token <b id=\"tokenCount\">0</b></button>\n          <span class=\"wallet-chip\">Coin <b id=\"coinCount\">0</b></span>\n        </div>\n        <div class=\"icon-row\" aria-label=\"Game controls\">\n          <button id=\"soundBtn\" class=\"icon-btn\" type=\"button\" aria-label=\"Toggle sound effects\">SFX</button>\n          <button id=\"musicBtn\" class=\"icon-btn\" type=\"button\" aria-label=\"Toggle music\">MUS</button>\n          <button id=\"pauseBtn\" class=\"icon-btn\" type=\"button\" aria-label=\"Pause\">II</button>\n          <button id=\"settingsBtn\" class=\"icon-btn\" type=\"button\" aria-label=\"Settings\">SET</button>\n        </div>\n      </header>\n\n      <div class=\"layout\">\n        <aside class=\"column left-column\">\n          <section class=\"panel order-panel\">\n            <div class=\"panel-title\">\n              <span>Customer Order</span>\n              <button id=\"orderInfoBtn\" class=\"tiny-btn\" type=\"button\" aria-label=\"Order help\">?</button>\n            </div>\n            <h2 id=\"orderTitle\">Warm up the line</h2>\n            <div class=\"bar\" aria-label=\"Order progress\"><i id=\"orderFill\"></i></div>\n            <p id=\"orderProgress\">0 / 0</p>\n            <button id=\"claimOrderBtn\" class=\"btn btn-primary hidden\" type=\"button\">Claim Reward</button>\n          </section>\n\n          <section class=\"panel route-panel\">\n            <div class=\"panel-title\">Factory Route</div>\n            <div id=\"factoryList\" class=\"factory-list\"></div>\n            <div class=\"bar\"><i id=\"factoryFill\"></i></div>\n            <p id=\"factoryProgressText\">0 / 100 shipments</p>\n          </section>\n        </aside>\n\n        <section class=\"play-column\">\n          <div id=\"tutorial\" class=\"tutorial hidden\">\n            <b id=\"tutorialTitle\">Drop an item</b>\n            <span id=\"tutorialText\">Tap Drop Item to place Scrap on the conveyor.</span>\n            <div>\n              <button id=\"tutorialNextBtn\" class=\"btn btn-small btn-primary\" type=\"button\">Next</button>\n              <button id=\"tutorialSkipBtn\" class=\"btn btn-small btn-soft\" type=\"button\">Skip</button>\n            </div>\n          </div>\n\n          <div class=\"factory-scene\" aria-hidden=\"true\">\n            <div class=\"sun\"></div>\n            <div class=\"cloud cloud-a\"></div>\n            <div class=\"cloud cloud-b\"></div>\n            <div class=\"building\"><span id=\"buildingLabel\">TOY<br>WORKS</span><i></i></div>\n            <div class=\"box-stack\"><span></span><span></span><span></span></div>\n          </div>\n\n          <div id=\"beltWrap\" class=\"belt-wrap\">\n            <div class=\"machine paint\" data-machine=\"paint\">\n              <div class=\"machine-head\"></div><b>Paint</b><small id=\"paintLabel\">Locked</small>\n            </div>\n            <div class=\"machine upgrade\" data-machine=\"upgrade\">\n              <div class=\"machine-head\"></div><b>Upgrade</b><small id=\"upgradeLabel\">Locked</small>\n            </div>\n            <div class=\"machine duplicate\" data-machine=\"duplicate\">\n              <div class=\"machine-head\"></div><b>Copy</b><small id=\"duplicateLabel\">Locked</small>\n            </div>\n            <div class=\"machine scanner\" data-machine=\"scanner\">\n              <div class=\"machine-head\"></div><b>Scan</b><small id=\"scannerLabel\">Locked</small>\n            </div>\n\n            <div id=\"belt\" class=\"belt\">\n              <div class=\"belt-stripes\"></div>\n              <div id=\"products\" class=\"products\"></div>\n            </div>\n            <div id=\"shippingGate\" class=\"shipping-gate\"><b>SHIP</b><span>&gt;</span></div>\n            <div id=\"blocked\" class=\"blocked hidden\">Line full. Merge to clear space.</div>\n          </div>\n\n          <div id=\"floatLayer\" class=\"float-layer\"></div>\n          <div id=\"particleLayer\" class=\"particle-layer\"></div>\n\n          <div class=\"drop-row\">\n            <button id=\"dropBtn\" class=\"drop-btn\" type=\"button\">\n              <span>+</span> Drop Item <i id=\"cooldownFill\"></i>\n            </button>\n            <p id=\"hint\">Drop Scrap, then drag matching products together.</p>\n          </div>\n        </section>\n\n        <aside class=\"column right-column\">\n          <section class=\"panel upgrades-panel\">\n            <div class=\"panel-title\">\n              <span>Upgrades</span>\n              <button id=\"upgradeInfoBtn\" class=\"tiny-btn\" type=\"button\" aria-label=\"Upgrade help\">?</button>\n            </div>\n            <div id=\"upgradeList\"></div>\n          </section>\n\n          <section class=\"panel machine-panel\">\n            <div class=\"panel-title\">Machines</div>\n            <div id=\"machineList\"></div>\n          </section>\n\n          <button id=\"prestigeBtn\" class=\"btn prestige-btn\" type=\"button\">Factory Reset</button>\n        </aside>\n      </div>\n\n      <footer class=\"footer\">\n        <span id=\"saveStatus\">Saved</span>\n        <span id=\"factoryMechanicText\">Toy Factory: combo orders give extra progress.</span>\n        <button id=\"helpBtn\" class=\"link-btn\" type=\"button\">How to play</button>\n      </footer>\n    </section>\n\n    <div id=\"modal\" class=\"modal hidden\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modalTitle\">\n      <div class=\"modal-card\">\n        <button id=\"modalCloseBtn\" class=\"close-btn\" type=\"button\" aria-label=\"Close\">x</button>\n        <div id=\"modalContent\"></div>\n      </div>\n    </div>\n  </main>\n  <script src=\"game.js\"></script>\n</body>\n</html>\n","styles.css":"@import url(\"https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800;900&display=swap\");\n\n:root {\n  --ink: #213047;\n  --muted: #637187;\n  --paper: #fffdf5;\n  --line: #e1d8c9;\n  --rose: #ee5778;\n  --rose-dark: #ba3155;\n  --sun: #f6bd3b;\n  --green: #55bd8b;\n  --blue: #4fa4da;\n  --violet: #725ac7;\n  --belt: #667789;\n  --belt-dark: #39495b;\n  --shadow: 0 5px 0 #cfc5b3, 0 12px 24px rgba(42, 54, 80, .22);\n}\n\n* { box-sizing: border-box; }\nhtml, body { min-height: 100%; }\nbody {\n  margin: 0;\n  color: var(--ink);\n  font-family: Nunito, Arial, sans-serif;\n  font-weight: 800;\n  background: #bfe9f9;\n  overflow-x: hidden;\n}\n\nbutton {\n  font: inherit;\n  font-weight: 900;\n  color: inherit;\n  border: 0;\n  cursor: pointer;\n  touch-action: manipulation;\n  transition: transform .12s ease, filter .12s ease;\n}\nbutton:hover { transform: translateY(-2px); filter: brightness(1.04); }\nbutton:active { transform: translateY(1px); }\nbutton:disabled { cursor: not-allowed; transform: none; filter: grayscale(.7); opacity: .68; }\n.hidden { display: none !important; }\n\n.start-screen {\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 18px;\n  background:\n    radial-gradient(circle at 18% 18%, #ffe899 0 7%, transparent 8%),\n    linear-gradient(#74cff0 0 55%, #9bd87e 56%);\n}\n.start-card {\n  width: min(520px, 100%);\n  padding: 38px;\n  text-align: center;\n  background: var(--paper);\n  border: 5px solid #fff;\n  border-radius: 28px;\n  box-shadow: 0 10px 0 #9fc2c9, 0 24px 52px rgba(34, 54, 82, .28);\n}\n.gear-logo {\n  width: 78px;\n  height: 78px;\n  display: grid;\n  place-items: center;\n  margin: 0 auto 18px;\n  color: #fff;\n  background: var(--sun);\n  border-radius: 24px;\n  box-shadow: inset 0 -9px #dc8d28;\n  transform: rotate(8deg);\n  font-size: 28px;\n}\n.eyebrow {\n  margin: 0 0 6px;\n  color: var(--violet);\n  text-transform: uppercase;\n  letter-spacing: .8px;\n  font-size: 13px;\n}\nh1 {\n  margin: 0 0 14px;\n  font-size: clamp(38px, 8vw, 64px);\n  line-height: .92;\n}\n.start-copy { max-width: 390px; margin: 0 auto 18px; color: var(--muted); font-size: 18px; }\n.micro { margin: 12px 0 0; color: #758092; font-size: 12px; }\n\n.btn {\n  border-radius: 12px;\n  padding: 10px 14px;\n  background: #edf1f5;\n  box-shadow: 0 3px 0 #c5ccd4;\n}\n.btn-primary {\n  color: #fff;\n  background: linear-gradient(#ff7592, #e84f75);\n  box-shadow: 0 4px 0 var(--rose-dark);\n}\n.btn-soft {\n  background: #eee9ff;\n  color: #5d4db4;\n  box-shadow: 0 3px 0 #c7bde9;\n}\n.btn-large { min-width: 188px; margin: 8px; padding: 14px 24px; font-size: 19px; }\n.btn-small { padding: 6px 10px; font-size: 12px; }\n\n.game-screen {\n  min-height: 100vh;\n  background: linear-gradient(var(--sky, #bcecff) 0 32%, var(--ground, #cae69e) 32%);\n}\n.topbar {\n  min-height: 66px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 10px 16px;\n  background: var(--paper);\n  box-shadow: 0 3px 0 #9ac7d7;\n  position: relative;\n  z-index: 10;\n}\n.brand { display: flex; align-items: center; gap: 8px; font-size: 21px; }\n.brand-mark {\n  width: 34px;\n  height: 34px;\n  display: grid;\n  place-items: center;\n  color: #fff;\n  background: var(--sun);\n  border-radius: 11px;\n  font-size: 13px;\n  box-shadow: inset 0 -5px #d88f28;\n}\n.brand b {\n  margin-left: 5px;\n  color: var(--rose);\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: .7px;\n}\n.wallet, .icon-row { display: flex; align-items: center; gap: 7px; }\n.wallet-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  min-height: 38px;\n  padding: 8px 11px;\n  border-radius: 12px;\n  background: #fff0bd;\n  box-shadow: inset 0 -3px #efd17a;\n}\nbutton.wallet-chip { border: 0; }\n.icon-btn, .tiny-btn, .link-btn {\n  padding: 8px 9px;\n  border-radius: 10px;\n  background: #eaf2f6;\n  box-shadow: 0 3px 0 #c5d2d9;\n  font-size: 12px;\n}\n.link-btn { color: #446f91; background: transparent; box-shadow: none; padding: 4px; }\n.layout {\n  width: min(1500px, 100%);\n  margin: 0 auto;\n  padding: 15px;\n  display: grid;\n  grid-template-columns: 240px minmax(500px, 1fr) 280px;\n  gap: 14px;\n}\n.column { display: flex; flex-direction: column; gap: 13px; }\n.panel {\n  background: var(--paper);\n  border: 3px solid #fff;\n  border-radius: 16px;\n  padding: 13px;\n  box-shadow: var(--shadow);\n}\n.panel-title {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  color: #52617a;\n  font-size: 13px;\n  letter-spacing: .5px;\n  text-transform: uppercase;\n}\n.order-panel h2 {\n  min-height: 43px;\n  margin: 10px 0 8px;\n  font-size: 18px;\n  line-height: 1.15;\n}\n.bar {\n  height: 12px;\n  overflow: hidden;\n  background: #e7e8e9;\n  border-radius: 999px;\n}\n.bar i {\n  display: block;\n  width: 0;\n  height: 100%;\n  background: linear-gradient(90deg, var(--green), #d2e85d);\n  border-radius: inherit;\n  transition: width .25s ease;\n}\n.panel p { margin: 8px 0 0; color: var(--muted); font-size: 12px; }\n.factory-list { display: flex; justify-content: space-between; gap: 5px; margin: 12px 0; }\n.factory-dot {\n  width: 31px;\n  height: 31px;\n  display: grid;\n  place-items: center;\n  border-radius: 50%;\n  color: #7d8795;\n  background: #e5e8eb;\n  font-size: 11px;\n}\n.factory-dot.unlocked { color: #fff; background: var(--green); }\n.factory-dot.current { color: #fff; background: var(--sun); box-shadow: 0 0 0 4px #ffe9a8; }\n\n.play-column { min-width: 0; position: relative; }\n.tutorial {\n  position: absolute;\n  left: 50%;\n  top: 10px;\n  z-index: 30;\n  width: min(390px, calc(100% - 18px));\n  padding: 10px 12px;\n  text-align: center;\n  background: #fffdf6;\n  border: 3px solid #ffd365;\n  border-radius: 15px;\n  box-shadow: var(--shadow);\n  transform: translateX(-50%);\n  font-size: 13px;\n}\n.tutorial b, .tutorial span { display: block; }\n.tutorial div { margin-top: 8px; }\n\n.factory-scene {\n  height: 122px;\n  position: relative;\n  overflow: hidden;\n  border-radius: 22px 22px 0 0;\n  background: linear-gradient(var(--sky, #78d2f2) 0 72%, var(--ground, #95d27c) 73%);\n}\n.sun {\n  position: absolute;\n  left: 22px;\n  top: 18px;\n  width: 46px;\n  height: 46px;\n  border-radius: 50%;\n  background: #ffe17a;\n  box-shadow: 0 0 0 10px rgba(255, 225, 122, .25);\n}\n.cloud {\n  position: absolute;\n  width: 72px;\n  height: 22px;\n  top: 28px;\n  border-radius: 24px;\n  background: rgba(255,255,255,.72);\n  animation: drift 16s linear infinite alternate;\n}\n.cloud:before, .cloud:after {\n  content: \"\";\n  position: absolute;\n  bottom: 0;\n  border-radius: 50%;\n  background: inherit;\n}\n.cloud:before { width: 32px; height: 32px; left: 13px; }\n.cloud:after { width: 25px; height: 25px; left: 40px; }\n.cloud-a { left: 17%; }\n.cloud-b { right: 11%; top: 58px; animation-duration: 22s; }\n.building {\n  position: absolute;\n  right: 17%;\n  bottom: 0;\n  width: 142px;\n  height: 96px;\n  display: grid;\n  place-items: center;\n  color: #fff7d7;\n  text-align: center;\n  line-height: .9;\n  background: var(--building, #e86970);\n  border: 5px solid rgba(53, 57, 80, .22);\n  border-bottom: 0;\n  border-radius: 15px 15px 0 0;\n  box-shadow: inset 12px 0 rgba(255,255,255,.18);\n}\n.building i {\n  position: absolute;\n  right: 20px;\n  top: -39px;\n  width: 24px;\n  height: 43px;\n  background: #718397;\n  border: 4px solid #506073;\n}\n.box-stack {\n  position: absolute;\n  left: 13%;\n  bottom: 8px;\n  width: 90px;\n  height: 60px;\n}\n.box-stack span {\n  position: absolute;\n  width: 36px;\n  height: 29px;\n  background: #c88943;\n  border: 4px solid #9b642e;\n  border-radius: 6px;\n}\n.box-stack span:nth-child(1) { left: 0; bottom: 0; transform: rotate(-5deg); }\n.box-stack span:nth-child(2) { left: 36px; bottom: 0; transform: rotate(4deg); }\n.box-stack span:nth-child(3) { left: 20px; bottom: 28px; transform: rotate(2deg); }\n\n.belt-wrap {\n  height: 280px;\n  position: relative;\n  padding: 42px 67px 0 10px;\n  background: var(--ground, #cae69e);\n}\n.belt {\n  height: 188px;\n  position: relative;\n  overflow: hidden;\n  background: var(--belt);\n  border: 8px solid var(--belt-dark);\n  border-radius: 16px;\n  box-shadow: inset 0 8px rgba(255,255,255,.16), inset 0 -9px rgba(0,0,0,.18);\n}\n.belt-stripes {\n  position: absolute;\n  inset: 0;\n  background: repeating-linear-gradient(135deg, #5a6b7d 0 18px, #718496 19px 38px);\n  animation: beltMove .8s linear infinite;\n}\n.belt.slow .belt-stripes { animation-duration: 1.7s; }\n.products { position: absolute; inset: 0; z-index: 2; }\n.shipping-gate {\n  position: absolute;\n  top: 72px;\n  right: 0;\n  width: 62px;\n  height: 160px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  color: #84540d;\n  background: #f7c55d;\n  border: 6px solid #b87b25;\n  border-right: 0;\n  border-radius: 14px 0 0 14px;\n  z-index: 15;\n}\n.shipping-gate span { font-size: 28px; }\n.blocked {\n  position: absolute;\n  left: 50%;\n  bottom: 36px;\n  z-index: 20;\n  padding: 7px 12px;\n  color: #fff;\n  background: #e95e72;\n  border-radius: 9px;\n  font-size: 12px;\n  transform: translateX(-50%);\n  animation: pulse .8s infinite alternate;\n}\n\n.machine {\n  position: absolute;\n  top: 2px;\n  z-index: 14;\n  width: 74px;\n  padding: 5px 4px 4px;\n  text-align: center;\n  color: #fff;\n  background: #596a7b;\n  border-radius: 10px 10px 0 0;\n  filter: drop-shadow(0 4px 0 rgba(40, 48, 60, .45));\n}\n.machine b { display: block; font-size: 10px; }\n.machine small { display: block; color: #d9f5ff; font-size: 9px; }\n.machine-head {\n  width: 28px;\n  height: 22px;\n  margin: 0 auto 2px;\n  border-radius: 7px;\n  background: rgba(255,255,255,.28);\n  box-shadow: inset 0 -4px rgba(0,0,0,.14);\n}\n.paint { left: 20%; background: #4fa4da; }\n.upgrade { left: 41%; background: #775ec6; }\n.duplicate { left: 62%; background: #35a996; }\n.scanner { left: 82%; background: #db8146; }\n.machine.locked { filter: grayscale(1) brightness(.75); opacity: .86; }\n.machine.active { animation: machinePop .35s ease; }\n.machine.active .machine-head { animation: headSpin .35s ease; }\n\n.product {\n  position: absolute;\n  z-index: 5;\n  width: 58px;\n  height: 58px;\n  display: grid;\n  place-items: center;\n  border: 4px solid #fff8d9;\n  box-shadow: 0 5px 0 rgba(0,0,0,.22), inset 0 -8px rgba(0,0,0,.15);\n  cursor: grab;\n  user-select: none;\n  touch-action: none;\n  will-change: left, top, transform;\n}\n.product:before {\n  content: attr(data-mark);\n  color: rgba(255,255,255,.95);\n  font-size: 20px;\n  text-shadow: 0 2px rgba(0,0,0,.18);\n}\n.product:after {\n  content: attr(data-level);\n  position: absolute;\n  right: -7px;\n  bottom: -8px;\n  width: 21px;\n  height: 21px;\n  display: grid;\n  place-items: center;\n  color: #415164;\n  background: #fff;\n  border: 2px solid currentColor;\n  border-radius: 50%;\n  font-size: 12px;\n}\n.product.dragging {\n  z-index: 25;\n  cursor: grabbing;\n  transform: scale(1.12);\n  box-shadow: 0 0 0 5px rgba(255,255,255,.7), 0 8px 0 rgba(0,0,0,.2);\n}\n.product.pop { animation: productPop .32s ease; }\n.lvl1 { background: #b58962; border-radius: 16px; }\n.lvl2 { background: #5cc4b8; border-radius: 12px; }\n.lvl3 { background: #e87584; border-radius: 50%; }\n.lvl4 { background: #697fda; border-radius: 13px; }\n.lvl5 { background: #f3b43d; border-radius: 24px 24px 12px 12px; }\n\n.drop-row { padding: 13px 0 0; text-align: center; }\n.drop-btn {\n  position: relative;\n  min-width: 220px;\n  overflow: hidden;\n  padding: 13px 27px;\n  color: #fff;\n  background: linear-gradient(#ff7592, #e84f75);\n  border-radius: 15px;\n  box-shadow: 0 5px 0 var(--rose-dark);\n  font-size: 20px;\n}\n.drop-btn span { display: inline-block; margin-right: 5px; font-size: 26px; vertical-align: -2px; }\n.drop-btn i {\n  position: absolute;\n  left: 0;\n  bottom: 0;\n  width: 0;\n  height: 5px;\n  background: rgba(255,255,255,.75);\n}\n#hint { margin: 8px 0 0; color: #415d72; font-size: 13px; }\n\n.upgrade-row, .machine-row, .token-row {\n  padding: 10px 0;\n  border-bottom: 1px dashed #d8d3c7;\n}\n.upgrade-row:last-child, .machine-row:last-child, .token-row:last-child { border-bottom: 0; }\n.upgrade-row b, .machine-row b, .token-row b { display: block; font-size: 14px; }\n.upgrade-row small, .machine-row small, .token-row small { display: block; color: var(--muted); font-size: 11px; margin: 2px 0 7px; }\n.buy-btn {\n  width: 100%;\n  padding: 7px 9px;\n  color: #5b4ab0;\n  background: #eee9ff;\n  border-radius: 9px;\n  box-shadow: 0 3px 0 #c7bde9;\n  font-size: 12px;\n}\n.machine-row {\n  display: grid;\n  grid-template-columns: 34px 1fr;\n  align-items: center;\n  gap: 7px;\n}\n.machine-icon {\n  width: 31px;\n  height: 31px;\n  display: grid;\n  place-items: center;\n  color: #fff;\n  background: #8b98a9;\n  border-radius: 10px;\n  font-size: 11px;\n}\n.machine-row .buy-btn { grid-column: 1 / -1; }\n.prestige-btn {\n  margin-top: auto;\n  color: #6e4fac;\n  background: #f2e8ff;\n  box-shadow: 0 3px 0 #cdb5e0;\n}\n\n.float-layer, .particle-layer {\n  position: absolute;\n  inset: 0;\n  z-index: 40;\n  pointer-events: none;\n}\n.float {\n  position: absolute;\n  color: #fff;\n  text-shadow: 0 2px rgba(34, 45, 62, .45);\n  animation: floatUp .95s ease forwards;\n  white-space: nowrap;\n}\n.float.coin { color: #ffdc64; }\n.particle {\n  position: absolute;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--sun);\n  animation: burst .55s ease forwards;\n}\n\n.footer {\n  width: min(1500px, 100%);\n  margin: 0 auto;\n  padding: 2px 18px 14px;\n  display: flex;\n  justify-content: space-between;\n  gap: 8px;\n  color: #52667a;\n  font-size: 12px;\n}\n#saveStatus { color: #2f8a66; }\n\n.modal {\n  position: fixed;\n  inset: 0;\n  z-index: 100;\n  display: grid;\n  place-items: center;\n  padding: 16px;\n  background: rgba(24, 44, 59, .62);\n}\n.modal-card {\n  position: relative;\n  width: min(520px, 100%);\n  max-height: 90vh;\n  overflow: auto;\n  padding: 26px;\n  text-align: center;\n  background: var(--paper);\n  border: 5px solid #fff;\n  border-radius: 22px;\n  box-shadow: 0 12px 0 rgba(36, 60, 75, .35);\n}\n.modal-card h2 { margin: 2px 0 10px; }\n.modal-card p { color: var(--muted); font-size: 14px; }\n.close-btn {\n  position: absolute;\n  right: 10px;\n  top: 8px;\n  padding: 5px 9px;\n  background: transparent;\n  box-shadow: none;\n  font-size: 20px;\n}\n.danger-btn {\n  color: #a9354d;\n  background: #ffe7ec;\n  box-shadow: 0 3px 0 #e7b8c2;\n}\n\n.theme-candy { --sky: #ffd9ec; --ground: #b9e9c6; --building: #ee72a3; }\n.theme-robot { --sky: #cde7ff; --ground: #c9d3dd; --building: #65798d; }\n.theme-potion { --sky: #d8ccff; --ground: #bfe4ce; --building: #795cc2; }\n.theme-space { --sky: #1f315c; --ground: #8d91b2; --building: #4c5cc6; }\n.theme-space .factory-scene { color: #fff; }\n.theme-space .sun { background: #dfe7ff; box-shadow: 0 0 0 10px rgba(223,231,255,.15); }\n\n@keyframes beltMove { to { background-position: 56px 0; } }\n@keyframes drift { to { transform: translateX(62px); } }\n@keyframes productPop { 50% { transform: scale(1.42) rotate(8deg); } }\n@keyframes floatUp { to { transform: translateY(-46px); opacity: 0; } }\n@keyframes burst { to { transform: translate(var(--x), var(--y)) scale(0); opacity: 0; } }\n@keyframes machinePop { 50% { filter: brightness(1.7) drop-shadow(0 0 10px rgba(255,255,255,.7)); } }\n@keyframes headSpin { to { transform: rotate(360deg); } }\n@keyframes pulse { to { transform: translateX(-50%) scale(1.04); } }\n\n@media (prefers-reduced-motion: reduce) {\n  *, *:before, *:after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n\n@media (max-width: 1020px) {\n  .layout { grid-template-columns: 1fr; max-width: 760px; }\n  .left-column, .right-column { display: grid; grid-template-columns: 1fr 1fr; }\n  .prestige-btn { margin-top: 0; }\n}\n\n@media (max-width: 620px) {\n  .topbar { min-height: 56px; padding: 7px 8px; gap: 5px; }\n  .brand { font-size: 15px; gap: 5px; }\n  .brand b { display: none; }\n  .brand-mark { width: 29px; height: 29px; border-radius: 9px; }\n  .wallet { gap: 4px; }\n  .wallet-chip { min-height: 32px; padding: 6px 7px; font-size: 12px; }\n  .icon-row { gap: 3px; }\n  .icon-btn { padding: 7px 6px; font-size: 10px; }\n  .layout { padding: 8px; gap: 9px; }\n  .left-column, .right-column { display: flex; }\n  .factory-scene { height: 78px; }\n  .building { right: 10%; transform: scale(.66); transform-origin: bottom; }\n  .box-stack { transform: scale(.7); transform-origin: bottom left; }\n  .sun, .cloud { display: none; }\n  .belt-wrap { height: 238px; padding: 34px 50px 0 6px; }\n  .belt { height: 164px; border-width: 7px; }\n  .shipping-gate { top: 57px; width: 49px; height: 149px; font-size: 12px; }\n  .machine { width: 61px; transform: scale(.82); transform-origin: bottom; }\n  .paint { left: 15%; }\n  .upgrade { left: 36%; }\n  .duplicate { left: 57%; }\n  .scanner { left: 77%; }\n  .product { width: 51px; height: 51px; }\n  .drop-btn { min-width: 204px; padding: 12px 21px; font-size: 18px; }\n  .footer span:nth-child(2) { display: none; }\n}\n","game.js":"/* Tiny Factory Drop - standalone browser factory merge game. */\nconst $ = (selector) => document.querySelector(selector);\nconst $$ = (selector) => [...document.querySelectorAll(selector)];\n\nconst SAVE_KEY = \"tinyFactoryDrop_v2\";\nconst PRODUCT_VALUES = [0, 1, 4, 12, 35, 100];\nconst PRODUCT_NAMES = [\"\", \"Scrap\", \"Parts\", \"Gadget\", \"Robot\", \"Super Machine\"];\nconst PRODUCT_MARKS = [\n  null,\n  [\"S\", \"P\", \"G\", \"R\", \"M\"],\n  [\"C\", \"T\", \"L\", \"B\", \"K\"],\n  [\"N\", \"B\", \"D\", \"A\", \"X\"],\n  [\"H\", \"V\", \"F\", \"O\", \"E\"],\n  [\"M\", \"S\", \"P\", \"Z\", \"Q\"]\n];\n\nconst FACTORIES = [\n  { name: \"Toy Factory\", short: \"TOY\", theme: \"toy\", goal: 90, bonus: 1, mechanic: \"Combo order progress grows faster after quick merges.\" },\n  { name: \"Candy Factory\", short: \"CANDY\", theme: \"candy\", goal: 210, bonus: 1.35, mechanic: \"Occasional bonus Scrap drops with each tap.\" },\n  { name: \"Robot Factory\", short: \"BOT\", theme: \"robot\", goal: 470, bonus: 1.8, mechanic: \"Robots trigger a short scanner speed boost.\" },\n  { name: \"Potion Factory\", short: \"POTION\", theme: \"potion\", goal: 950, bonus: 2.45, mechanic: \"Painted products can gain a bubbling value bonus.\" },\n  { name: \"Space Factory\", short: \"SPACE\", theme: \"space\", goal: 1800, bonus: 3.35, mechanic: \"Super Machines can launch a small token spark.\" }\n];\n\nconst UPGRADES = {\n  drop: { name: \"Drop Speed\", desc: \"Shorter button cooldown\", base: 10, max: 10 },\n  speed: { name: \"Belt Motor\", desc: \"Faster conveyor movement\", base: 16, max: 10 },\n  value: { name: \"Sale Value\", desc: \"More coins from shipping\", base: 22, max: 10 },\n  quality: { name: \"Better Materials\", desc: \"Chance to drop Parts\", base: 34, max: 7 },\n  auto: { name: \"Auto Dropper\", desc: \"Drops while space is open\", base: 70, max: 5 },\n  machineChance: { name: \"Machine Chance\", desc: \"More machine activations\", base: 85, max: 8 },\n  machinePower: { name: \"Machine Power\", desc: \"Stronger machine results\", base: 95, max: 8 },\n  capacity: { name: \"Belt Space\", desc: \"More products can fit\", base: 45, max: 7 },\n  order: { name: \"Order Rewards\", desc: \"Bigger order payouts\", base: 55, max: 8 }\n};\n\nconst MACHINES = {\n  paint: { name: \"Paint Machine\", icon: \"PNT\", desc: \"Raises sale value\", base: 58, max: 5 },\n  upgrade: { name: \"Upgrade Machine\", icon: \"UP\", desc: \"May raise product level\", base: 96, max: 5 },\n  duplicate: { name: \"Duplicator\", icon: \"DUP\", desc: \"May copy a product\", base: 140, max: 5 },\n  scanner: { name: \"Speed Scanner\", icon: \"SPD\", desc: \"High levels boost belt speed\", base: 185, max: 5 }\n};\n\nconst TOKEN_UPGRADES = {\n  earn: { name: \"Coin Earnings\", desc: \"+5% coins per level\" },\n  merge: { name: \"Merge Value\", desc: \"Merged items ship for more\" },\n  drop: { name: \"Drop Speed\", desc: \"-3% cooldown per level\" },\n  rare: { name: \"Rare Products\", desc: \"+1.5% Parts chance per level\" },\n  order: { name: \"Order Rewards\", desc: \"+8% order rewards per level\" }\n};\n\nlet state;\nlet items = [];\nlet nextId = 0;\nlet dragging = null;\nlet lastFrame = 0;\nlet cooldownUntil = 0;\nlet paused = false;\nlet started = false;\nlet audioCtx = null;\nlet musicTimer = null;\nlet saveTimer = null;\nlet autoTimer = null;\nlet speedBoostUntil = 0;\nlet lastMergeAt = 0;\n\nfunction freshState() {\n  return {\n    coins: 14,\n    tokens: 0,\n    factory: 0,\n    progress: 0,\n    upgrades: Object.fromEntries(Object.keys(UPGRADES).map((key) => [key, 0])),\n    machines: Object.fromEntries(Object.keys(MACHINES).map((key) => [key, 0])),\n    order: makeOrder(0),\n    lifetimeEarned: 14,\n    sound: true,\n    music: true,\n    tutorial: 0,\n    tutorialDone: false,\n    prestige: Object.fromEntries(Object.keys(TOKEN_UPGRADES).map((key) => [key, 0]))\n  };\n}\n\nfunction load() {\n  const base = freshState();\n  try {\n    const raw = localStorage.getItem(SAVE_KEY);\n    state = raw ? { ...base, ...JSON.parse(raw) } : base;\n  } catch (error) {\n    console.warn(\"Tiny Factory Drop save could not be loaded; starting fresh.\", error);\n    state = base;\n  }\n  state.upgrades = { ...base.upgrades, ...state.upgrades };\n  state.machines = { ...base.machines, ...state.machines };\n  state.prestige = { ...base.prestige, ...state.prestige };\n  state.order = { ...base.order, ...state.order };\n  state.factory = clamp(Number(state.factory) || 0, 0, FACTORIES.length - 1);\n  state.coins = Math.max(0, Number(state.coins) || 0);\n  state.tokens = Math.max(0, Number(state.tokens) || 0);\n  state.progress = Math.max(0, Number(state.progress) || 0);\n}\n\nfunction save() {\n  try {\n    localStorage.setItem(SAVE_KEY, JSON.stringify(state));\n    $(\"#saveStatus\").textContent = \"Saved\";\n    window.clearTimeout(save.statusTimer);\n    save.statusTimer = window.setTimeout(() => $(\"#saveStatus\").textContent = \"Autosaving\", 1400);\n  } catch (error) {\n    console.warn(\"Tiny Factory Drop save failed.\", error);\n    $(\"#saveStatus\").textContent = \"Save failed\";\n  }\n}\n\nfunction startGame() {\n  if (started) return;\n  started = true;\n  load();\n  $(\"#startScreen\").classList.add(\"hidden\");\n  $(\"#gameScreen\").classList.remove(\"hidden\");\n  renderAll();\n  if (!state.tutorialDone) showTutorial();\n  startMusic();\n  saveTimer = window.setInterval(save, 8000);\n  autoTimer = window.setInterval(autoDropTick, 350);\n  requestAnimationFrame(loop);\n}\n\nfunction renderAll() {\n  const factory = FACTORIES[state.factory];\n  const app = $(\"#app\");\n  app.className = `theme-${factory.theme}`;\n  $(\"#factoryName\").textContent = factory.name;\n  $(\"#buildingLabel\").innerHTML = `${factory.short}<br>WORKS`;\n  $(\"#coinCount\").textContent = formatNumber(state.coins);\n  $(\"#tokenCount\").textContent = formatNumber(state.tokens);\n  $(\"#factoryMechanicText\").textContent = `${factory.name}: ${factory.mechanic}`;\n  $(\"#factoryFill\").style.width = `${Math.min(100, (state.progress / factory.goal) * 100)}%`;\n  $(\"#factoryProgressText\").textContent = `${Math.floor(state.progress)} / ${factory.goal} shipments`;\n  $(\"#factoryList\").innerHTML = FACTORIES.map((item, index) => {\n    const className = index === state.factory ? \"current\" : index < state.factory ? \"unlocked\" : \"\";\n    return `<span class=\"factory-dot ${className}\" title=\"${item.name}\">${index + 1}</span>`;\n  }).join(\"\");\n  renderOrder();\n  renderUpgrades();\n  renderMachines();\n  renderAudioButtons();\n}\n\nfunction renderOrder() {\n  const order = state.order;\n  $(\"#orderTitle\").textContent = order.done ? \"Order ready to claim\" : orderText(order);\n  $(\"#orderProgress\").textContent = `${Math.floor(order.progress)} / ${order.target} - reward ${formatNumber(order.reward)} coins + ${order.points} token`;\n  $(\"#orderFill\").style.width = `${Math.min(100, (order.progress / order.target) * 100)}%`;\n  $(\"#claimOrderBtn\").classList.toggle(\"hidden\", !order.done);\n}\n\nfunction renderUpgrades() {\n  $(\"#upgradeList\").innerHTML = Object.entries(UPGRADES).map(([key, upgrade]) => {\n    const level = state.upgrades[key];\n    const maxed = level >= upgrade.max;\n    const price = cost(upgrade.base, level);\n    const disabled = maxed || state.coins < price ? \"disabled\" : \"\";\n    const label = maxed ? \"Maxed\" : `Buy ${formatNumber(price)}`;\n    return `\n      <div class=\"upgrade-row\">\n        <b>${upgrade.name} Lv.${level}</b>\n        <small>${upgrade.desc} - ${maxed ? \"maximum reached\" : nextBenefit(key, level + 1)}</small>\n        <button class=\"buy-btn\" data-buy-upgrade=\"${key}\" ${disabled} type=\"button\">${label}</button>\n      </div>`;\n  }).join(\"\");\n}\n\nfunction renderMachines() {\n  $(\"#machineList\").innerHTML = Object.entries(MACHINES).map(([key, machine]) => {\n    const level = state.machines[key];\n    const maxed = level >= machine.max;\n    const price = cost(machine.base, level);\n    const disabled = maxed || state.coins < price ? \"disabled\" : \"\";\n    return `\n      <div class=\"machine-row\">\n        <span class=\"machine-icon\">${machine.icon}</span>\n        <div><b>${machine.name} Lv.${level}</b><small>${machine.desc}</small></div>\n        <button class=\"buy-btn\" data-buy-machine=\"${key}\" ${disabled} type=\"button\">${maxed ? \"Maxed\" : `Buy ${formatNumber(price)}`}</button>\n      </div>`;\n  }).join(\"\");\n  $(\"#paintLabel\").textContent = state.machines.paint ? `x${paintMultiplier().toFixed(2)}` : \"Locked\";\n  $(\"#upgradeLabel\").textContent = state.machines.upgrade ? `${Math.round(upgradeChance() * 100)}%` : \"Locked\";\n  $(\"#duplicateLabel\").textContent = state.machines.duplicate ? `${Math.round(duplicateChance() * 100)}%` : \"Locked\";\n  $(\"#scannerLabel\").textContent = state.machines.scanner ? `${scannerSeconds().toFixed(1)}s` : \"Locked\";\n  Object.keys(MACHINES).forEach((key) => {\n    $(`.machine[data-machine=\"${key}\"]`).classList.toggle(\"locked\", !state.machines[key]);\n  });\n}\n\nfunction renderAudioButtons() {\n  $(\"#soundBtn\").textContent = state.sound ? \"SFX\" : \"OFF\";\n  $(\"#musicBtn\").textContent = state.music ? \"MUS\" : \"OFF\";\n}\n\nfunction nextBenefit(key, level) {\n  const benefits = {\n    drop: `${dropCooldown(level).toFixed(2)}s cooldown`,\n    speed: `+${level * 12}% belt speed`,\n    value: `+${level * 10}% sale coins`,\n    quality: `${level * 8}% Parts chance`,\n    auto: `auto every ${autoInterval(level).toFixed(1)}s`,\n    machineChance: `+${level * 10}% machine odds`,\n    machinePower: `+${level * 9}% machine strength`,\n    capacity: `${capacity(level)} product spaces`,\n    order: `+${level * 12}% order coins`\n  };\n  return benefits[key];\n}\n\nfunction cost(base, level) {\n  return Math.floor(base * Math.pow(1.58, level));\n}\n\nfunction dropCooldown(level = state.upgrades.drop) {\n  const prestige = 1 - state.prestige.drop * 0.03;\n  return Math.max(0.34, (1.08 - level * 0.075) * Math.max(0.65, prestige));\n}\n\nfunction autoInterval(level = state.upgrades.auto) {\n  return Math.max(1.15, 4.2 - level * 0.45);\n}\n\nfunction capacity(level = state.upgrades.capacity) {\n  return 8 + level;\n}\n\nfunction dropItem(force = false) {\n  const now = performance.now();\n  const cooldownMs = dropCooldown() * 1000;\n  if (!force && now < cooldownUntil) return false;\n  if (items.length >= capacity()) {\n    setBlocked(true);\n    return false;\n  }\n\n  if (!force) cooldownUntil = now + cooldownMs;\n  const rareChance = state.upgrades.quality * 0.08 + state.prestige.rare * 0.015;\n  const level = Math.random() < rareChance ? 2 : 1;\n  spawnProduct(level, 15 + Math.random() * 9, 54 + Math.random() * 72, { fromMerge: false });\n\n  if (state.factory >= 1 && Math.random() < 0.09 && items.length < capacity()) {\n    spawnProduct(1, 12, 112, { fromMerge: false });\n    floatText(\"Candy bonus\", null, 62, 122);\n  }\n\n  beep(280, 0.08);\n  tutorialEvent(\"drop\");\n  renderAll();\n  return true;\n}\n\nfunction spawnProduct(level, x, y, options = {}) {\n  if (items.length >= capacity()) return null;\n  const product = {\n    id: ++nextId,\n    level,\n    x,\n    y,\n    valueBonus: options.valueBonus || 1,\n    processed: {},\n    born: performance.now()\n  };\n  const el = document.createElement(\"div\");\n  el.className = `product lvl${level}`;\n  el.dataset.id = String(product.id);\n  product.el = el;\n  updateProductElement(product);\n  el.style.left = `${product.x}px`;\n  el.style.top = `${product.y}px`;\n  el.addEventListener(\"pointerdown\", beginDrag);\n  $(\"#products\").appendChild(el);\n  items.push(product);\n  if (options.fromMerge) el.classList.add(\"pop\");\n  return product;\n}\n\nfunction updateProductElement(product) {\n  product.el.className = `product lvl${product.level}${product.el.classList.contains(\"dragging\") ? \" dragging\" : \"\"}`;\n  product.el.dataset.level = String(product.level);\n  const marks = PRODUCT_MARKS[state.factory] || PRODUCT_MARKS[0];\n  product.el.dataset.mark = marks[product.level - 1] || PRODUCT_NAMES[product.level][0] || \"?\";\n  product.el.setAttribute(\"aria-label\", PRODUCT_NAMES[product.level]);\n}\n\nfunction beginDrag(event) {\n  if (paused) return;\n  const product = items.find((item) => item.id === Number(event.currentTarget.dataset.id));\n  if (!product) return;\n  const rect = product.el.getBoundingClientRect();\n  dragging = {\n    product,\n    pointerId: event.pointerId,\n    dx: event.clientX - rect.left,\n    dy: event.clientY - rect.top\n  };\n  product.el.setPointerCapture?.(event.pointerId);\n  product.el.classList.add(\"dragging\");\n  event.preventDefault();\n}\n\nwindow.addEventListener(\"pointermove\", (event) => {\n  if (!dragging) return;\n  const area = $(\"#products\").getBoundingClientRect();\n  const size = productSize();\n  const product = dragging.product;\n  product.x = clamp(event.clientX - area.left - dragging.dx, 0, area.width - size);\n  product.y = clamp(event.clientY - area.top - dragging.dy, 0, area.height - size);\n  placeProduct(product);\n  event.preventDefault();\n}, { passive: false });\n\nwindow.addEventListener(\"pointerup\", () => {\n  if (!dragging) return;\n  const product = dragging.product;\n  product.el.classList.remove(\"dragging\");\n  dragging = null;\n  const match = items.find((item) => item !== product && item.level === product.level && distance(item, product) < productSize() * 0.86);\n  if (match) mergeProducts(product, match);\n  tutorialEvent(\"drag\");\n});\n\nfunction mergeProducts(a, b) {\n  if (!items.includes(a) || !items.includes(b) || a.level !== b.level) return;\n  if (a.level >= 5) {\n    floatText(\"Max level\", null, a.x, a.y);\n    return;\n  }\n  const level = a.level + 1;\n  const x = (a.x + b.x) / 2;\n  const y = (a.y + b.y) / 2;\n  const quick = performance.now() - lastMergeAt < 2200;\n  lastMergeAt = performance.now();\n  removeProduct(a);\n  removeProduct(b);\n  const merged = spawnProduct(level, x, y, { fromMerge: true, valueBonus: 1 + state.prestige.merge * 0.04 });\n  burst(x + 24, y + 24, \"#ffd66a\");\n  floatText(PRODUCT_NAMES[level], null, x + 20, y);\n  beep(450 + level * 100, 0.1);\n  tally(\"merge\", state.factory === 0 && quick ? 2 : 1);\n  tally(`create${level}`, 1);\n  tutorialEvent(\"merge\");\n  if (state.factory >= 2 && level >= 4) triggerScanner();\n  if (merged) processMachines(merged);\n  save();\n}\n\nfunction removeProduct(product) {\n  product.el?.remove();\n  items = items.filter((item) => item !== product);\n}\n\nfunction placeProduct(product) {\n  product.el.style.left = `${product.x}px`;\n  product.el.style.top = `${product.y}px`;\n}\n\nfunction loop(time) {\n  const dt = Math.min(50, time - lastFrame || 16);\n  lastFrame = time;\n  if (!paused) {\n    moveProducts(dt);\n    updateCooldown();\n  }\n  requestAnimationFrame(loop);\n}\n\nfunction moveProducts(dt) {\n  const belt = $(\"#belt\");\n  const beltWidth = $(\"#products\").clientWidth;\n  const boost = performance.now() < speedBoostUntil ? 1.75 : 1;\n  const speed = (0.032 + state.upgrades.speed * 0.0042) * (1 + state.factory * 0.045) * boost;\n  for (const product of [...items]) {\n    if (dragging?.product !== product) {\n      product.x += speed * dt;\n      avoidPermanentOverlap(product);\n      placeProduct(product);\n    }\n    processMachines(product);\n    if (product.x > beltWidth - productSize() * 0.64) sellProduct(product);\n  }\n  const full = items.length >= capacity();\n  setBlocked(full);\n  belt.classList.toggle(\"slow\", full && performance.now() >= speedBoostUntil);\n}\n\nfunction avoidPermanentOverlap(product) {\n  for (const other of items) {\n    if (other === product || dragging?.product === other || product.level === other.level) continue;\n    if (distance(product, other) < productSize() * 0.72) {\n      product.y += product.y < other.y ? -0.28 : 0.28;\n      product.y = clamp(product.y, 0, $(\"#products\").clientHeight - productSize());\n    }\n  }\n}\n\nfunction processMachines(product) {\n  const width = $(\"#products\").clientWidth || 1;\n  const pos = product.x / width;\n  const stops = { paint: 0.2, upgrade: 0.42, duplicate: 0.63, scanner: 0.84 };\n  for (const [key, at] of Object.entries(stops)) {\n    if (pos > at && !product.processed[key] && state.machines[key]) {\n      product.processed[key] = true;\n      activateMachine(key);\n      if (key === \"paint\") applyPaint(product);\n      if (key === \"upgrade\") applyUpgradeMachine(product);\n      if (key === \"duplicate\") applyDuplicator(product);\n      if (key === \"scanner\" && product.level >= 4) triggerScanner();\n    }\n  }\n}\n\nfunction applyPaint(product) {\n  product.valueBonus *= paintMultiplier();\n  if (state.factory >= 3 && Math.random() < 0.16) {\n    product.valueBonus *= 1.35;\n    floatText(\"Bubble bonus\", null, product.x, product.y);\n  }\n}\n\nfunction applyUpgradeMachine(product) {\n  if (product.level >= 5) return;\n  if (Math.random() < upgradeChance()) {\n    product.level += 1;\n    updateProductElement(product);\n    product.el.classList.add(\"pop\");\n    burst(product.x + 25, product.y + 25, \"#bca1ff\");\n    floatText(\"Upgraded\", null, product.x, product.y);\n    tally(`create${product.level}`, 1);\n  }\n}\n\nfunction applyDuplicator(product) {\n  if (items.length >= capacity()) return;\n  if (Math.random() < duplicateChance()) {\n    spawnProduct(product.level, Math.max(0, product.x - 48), clamp(product.y + 12, 0, $(\"#products\").clientHeight - productSize()), { valueBonus: product.valueBonus });\n    floatText(\"Copy\", null, product.x, product.y);\n  }\n}\n\nfunction activateMachine(key) {\n  const el = $(`.machine[data-machine=\"${key}\"]`);\n  el.classList.remove(\"active\");\n  void el.offsetWidth;\n  el.classList.add(\"active\");\n  beep(key === \"paint\" ? 390 : key === \"upgrade\" ? 640 : key === \"duplicate\" ? 530 : 760, 0.07);\n}\n\nfunction paintMultiplier() {\n  return 1.08 + state.machines.paint * 0.1 + state.upgrades.machinePower * 0.012;\n}\n\nfunction upgradeChance() {\n  return Math.min(0.55, 0.045 + state.machines.upgrade * 0.035 + state.upgrades.machineChance * 0.01);\n}\n\nfunction duplicateChance() {\n  return Math.min(0.42, 0.03 + state.machines.duplicate * 0.028 + state.upgrades.machineChance * 0.008);\n}\n\nfunction scannerSeconds() {\n  return 1.8 + state.machines.scanner * 0.35 + state.upgrades.machinePower * 0.08;\n}\n\nfunction triggerScanner() {\n  if (!state.machines.scanner && state.factory < 2) return;\n  speedBoostUntil = Math.max(speedBoostUntil, performance.now() + scannerSeconds() * 1000);\n  activateMachine(\"scanner\");\n  floatText(\"Speed boost\", null, $(\"#products\").clientWidth * 0.75, 22);\n}\n\nfunction sellProduct(product) {\n  if (!items.includes(product)) return;\n  let gain = PRODUCT_VALUES[product.level];\n  gain *= FACTORIES[state.factory].bonus;\n  gain *= 1 + state.upgrades.value * 0.1;\n  gain *= 1 + state.prestige.earn * 0.05;\n  gain *= product.valueBonus || 1;\n  gain = Math.max(1, Math.ceil(gain));\n  state.coins += gain;\n  state.lifetimeEarned += gain;\n  state.progress += product.level >= 4 ? 2 : 1;\n  if (state.factory >= 4 && product.level === 5 && Math.random() < 0.05) {\n    state.tokens += 1;\n    floatText(\"+1 token spark\", \"coin\", product.x, product.y - 18);\n  }\n  removeProduct(product);\n  floatText(`+${gain}`, \"coin\", $(\"#products\").clientWidth - 68, product.y + 12);\n  burst($(\"#products\").clientWidth - 32, product.y + 24, \"#ffda63\");\n  beep(800, 0.08);\n  tally(\"earn\", gain);\n  tally(`sell${product.level}`, 1);\n  tutorialEvent(\"sell\");\n  checkFactoryUnlock();\n  renderAll();\n}\n\nfunction checkFactoryUnlock() {\n  const factory = FACTORIES[state.factory];\n  if (state.progress >= factory.goal && state.factory < FACTORIES.length - 1) {\n    state.factory += 1;\n    state.progress = 0;\n    speedBoostUntil = performance.now() + 1800;\n    floatText(`${FACTORIES[state.factory].name} unlocked`, \"coin\", 260, 40);\n    burst(310, 80, \"#ffd66a\");\n    shake();\n    beep(980, 0.22);\n  }\n}\n\nfunction makeOrder(factoryIndex) {\n  const n = Math.min(factoryIndex, 4);\n  const orders = [\n    { type: \"merge\", target: 5 + n * 2, reward: 28 + n * 36, points: 1 },\n    { type: \"sell2\", target: 4 + n * 2, reward: 34 + n * 40, points: 1 },\n    { type: \"create3\", target: 2 + n, reward: 44 + n * 48, points: 1 },\n    { type: \"sell4\", target: 1 + Math.floor(n / 2), reward: 70 + n * 70, points: 1 + Math.floor(n / 2) },\n    { type: \"earn\", target: 55 + n * 80, reward: 42 + n * 55, points: 1 }\n  ];\n  const picked = orders[Math.floor(Math.random() * orders.length)];\n  return { ...picked, progress: 0, done: false };\n}\n\nfunction orderText(order) {\n  const text = {\n    merge: \"Perform product merges\",\n    sell2: \"Sell Parts\",\n    create3: \"Create Gadgets\",\n    sell4: \"Sell Robots\",\n    earn: \"Earn coins\"\n  };\n  return text[order.type] || \"Customer order\";\n}\n\nfunction tally(kind, amount = 1) {\n  const order = state.order;\n  if (order.done) return;\n  if (order.type !== kind) return;\n  order.progress = Math.min(order.target, order.progress + amount);\n  if (order.progress >= order.target) {\n    order.done = true;\n    floatText(\"Order complete\", \"coin\", 62, 72);\n    beep(900, 0.16);\n  }\n  renderOrder();\n}\n\nfunction claimOrder() {\n  const order = state.order;\n  if (!order.done) return;\n  const reward = Math.ceil(order.reward * (1 + state.upgrades.order * 0.12) * (1 + state.prestige.order * 0.08));\n  state.coins += reward;\n  state.lifetimeEarned += reward;\n  state.tokens += order.points;\n  state.progress += 8 + state.upgrades.order;\n  floatText(`+${reward} coins`, \"coin\", 68, 64);\n  floatText(`+${order.points} token`, \"coin\", 78, 92);\n  state.order = makeOrder(state.factory);\n  beep(920, 0.18);\n  checkFactoryUnlock();\n  renderAll();\n  save();\n}\n\nfunction buyUpgrade(key) {\n  const upgrade = UPGRADES[key];\n  const level = state.upgrades[key];\n  const price = cost(upgrade.base, level);\n  if (!upgrade || level >= upgrade.max || state.coins < price) return;\n  state.coins = Math.max(0, state.coins - price);\n  state.upgrades[key] += 1;\n  floatText(`${upgrade.name} up`, null, 210, 52);\n  beep(610, 0.1);\n  if (key === \"capacity\" || key === \"speed\") shake();\n  renderAll();\n  save();\n}\n\nfunction buyMachine(key) {\n  const machine = MACHINES[key];\n  const level = state.machines[key];\n  const price = cost(machine.base, level);\n  if (!machine || level >= machine.max || state.coins < price) return;\n  state.coins = Math.max(0, state.coins - price);\n  state.machines[key] += 1;\n  floatText(`${machine.name} ready`, null, 260, 35);\n  beep(700, 0.12);\n  shake();\n  renderAll();\n  save();\n}\n\nfunction autoDropTick() {\n  if (!started || paused || !state.upgrades.auto) return;\n  const now = performance.now();\n  if (!autoDropTick.next) autoDropTick.next = now + autoInterval() * 1000;\n  if (now >= autoDropTick.next) {\n    dropItem(true);\n    autoDropTick.next = now + autoInterval() * 1000;\n  }\n}\n\nfunction updateCooldown() {\n  const remaining = Math.max(0, cooldownUntil - performance.now());\n  const cooldown = dropCooldown() * 1000;\n  $(\"#cooldownFill\").style.width = `${(remaining / cooldown) * 100}%`;\n  $(\"#dropBtn\").disabled = paused || remaining > 0 || items.length >= capacity();\n}\n\nfunction setBlocked(value) {\n  $(\"#blocked\").classList.toggle(\"hidden\", !value);\n}\n\nfunction showTutorial() {\n  if (state.tutorialDone) return;\n  const steps = [\n    [\"Drop an item\", \"Tap Drop Item to place Scrap on the conveyor.\"],\n    [\"Drag products\", \"Drag with a mouse or finger. The page will stay still while you drag.\"],\n    [\"Merge matches\", \"Touch two matching products together to make the next product.\"],\n    [\"Ship products\", \"Items sell automatically when they reach the SHIP gate.\"],\n    [\"Buy upgrades\", \"Spend coins on Drop Speed or Belt Motor to grow faster.\"]\n  ];\n  if (state.tutorial >= steps.length) {\n    state.tutorialDone = true;\n    $(\"#tutorial\").classList.add(\"hidden\");\n    save();\n    return;\n  }\n  $(\"#tutorial\").classList.remove(\"hidden\");\n  $(\"#tutorialTitle\").textContent = steps[state.tutorial][0];\n  $(\"#tutorialText\").textContent = steps[state.tutorial][1];\n  $(\"#tutorialNextBtn\").textContent = state.tutorial === steps.length - 1 ? \"Finish\" : \"Next\";\n}\n\nfunction tutorialEvent(kind) {\n  if (state.tutorialDone) return;\n  const expected = [\"drop\", \"drag\", \"merge\", \"sell\"];\n  if (expected[state.tutorial] === kind) {\n    state.tutorial += 1;\n    showTutorial();\n  }\n}\n\nfunction openHelp() {\n  showModal(`\n    <h2 id=\"modalTitle\">How to play</h2>\n    <p>Drop Scrap onto the conveyor. Drag equal products together to merge them into better products. The shipping gate sells anything that reaches the end.</p>\n    <p>When the belt is full, dropping pauses until you merge or ship products. Orders, upgrades, machines, factory unlocks, and prestige all build from that loop.</p>\n    <button class=\"btn btn-primary\" type=\"button\" data-close-modal>Back to work</button>\n  `);\n}\n\nfunction openSettings() {\n  showModal(`\n    <h2 id=\"modalTitle\">Settings</h2>\n    <p>Progress autosaves on this browser. Audio is generated in the game, so it still runs if external audio is unavailable.</p>\n    <button id=\"resetSaveBtn\" class=\"btn danger-btn\" type=\"button\">Reset saved progress</button>\n  `);\n  $(\"#resetSaveBtn\").addEventListener(\"click\", () => {\n    if (window.confirm(\"Reset all Tiny Factory Drop progress? This cannot be undone.\")) {\n      localStorage.removeItem(SAVE_KEY);\n      location.reload();\n    }\n  });\n}\n\nfunction openPrestige() {\n  if (state.coins < 2500) {\n    showModal(`\n      <h2 id=\"modalTitle\">Factory Reset</h2>\n      <p>Prestige unlocks at 2,500 coins. You currently have ${formatNumber(state.coins)} coins.</p>\n      <p>When available, it resets coins, factory progress, upgrades, machines, orders, and loose products for permanent Factory Tokens.</p>\n      <button class=\"btn btn-primary\" type=\"button\" data-close-modal>Keep building</button>\n    `);\n    return;\n  }\n  const earned = Math.max(1, Math.floor(state.coins / 2500));\n  showModal(`\n    <h2 id=\"modalTitle\">Factory Reset</h2>\n    <p>Reset coins, upgrades, machines, current factory, orders, and conveyor products for ${earned} permanent Factory Tokens.</p>\n    <p>Your existing tokens and token upgrades stay forever.</p>\n    <button id=\"confirmPrestigeBtn\" class=\"btn btn-primary\" type=\"button\">Reset for ${earned} tokens</button>\n  `);\n  $(\"#confirmPrestigeBtn\").addEventListener(\"click\", () => {\n    const permanent = { tokens: state.tokens + earned, prestige: { ...state.prestige }, sound: state.sound, music: state.music, tutorialDone: true };\n    items.forEach((item) => item.el.remove());\n    items = [];\n    state = freshState();\n    state.tokens = permanent.tokens;\n    state.prestige = permanent.prestige;\n    state.sound = permanent.sound;\n    state.music = permanent.music;\n    state.tutorialDone = permanent.tutorialDone;\n    closeModal();\n    floatText(`+${earned} Factory Tokens`, \"coin\", 220, 70);\n    burst(250, 95, \"#ffd66a\");\n    shake();\n    beep(1020, 0.24);\n    renderAll();\n    save();\n  });\n}\n\nfunction openTokenShop() {\n  const rows = Object.entries(TOKEN_UPGRADES).map(([key, upgrade]) => `\n    <div class=\"token-row\">\n      <b>${upgrade.name} Lv.${state.prestige[key]}</b>\n      <small>${upgrade.desc}</small>\n      <button class=\"buy-btn\" data-buy-token=\"${key}\" ${state.tokens < 1 ? \"disabled\" : \"\"} type=\"button\">Spend 1 Token</button>\n    </div>\n  `).join(\"\");\n  showModal(`\n    <h2 id=\"modalTitle\">Factory Tokens: ${formatNumber(state.tokens)}</h2>\n    <p>Tokens are permanent and survive Factory Reset.</p>\n    ${rows}\n  `);\n}\n\nfunction buyTokenUpgrade(key) {\n  if (!TOKEN_UPGRADES[key] || state.tokens < 1) return;\n  state.tokens -= 1;\n  state.prestige[key] += 1;\n  beep(760, 0.1);\n  renderAll();\n  save();\n  openTokenShop();\n}\n\nfunction showModal(html) {\n  paused = true;\n  $(\"#modalContent\").innerHTML = html;\n  $(\"#modal\").classList.remove(\"hidden\");\n}\n\nfunction closeModal() {\n  $(\"#modal\").classList.add(\"hidden\");\n  paused = false;\n}\n\nfunction togglePause() {\n  if (paused && !$(\"#modal\").classList.contains(\"hidden\")) return;\n  paused = true;\n  showModal(`\n    <h2 id=\"modalTitle\">Production Paused</h2>\n    <p>The conveyor is stopped safely.</p>\n    <button class=\"btn btn-primary\" type=\"button\" data-close-modal>Resume</button>\n  `);\n}\n\nfunction floatText(text, kind, x, y) {\n  const el = document.createElement(\"span\");\n  el.className = `float ${kind || \"\"}`;\n  el.textContent = text;\n  el.style.left = `${x ?? 220}px`;\n  el.style.top = `${y ?? 120}px`;\n  $(\"#floatLayer\").appendChild(el);\n  window.setTimeout(() => el.remove(), 1000);\n}\n\nfunction burst(x, y, color) {\n  for (let i = 0; i < 10; i += 1) {\n    const particle = document.createElement(\"i\");\n    particle.className = \"particle\";\n    particle.style.left = `${x}px`;\n    particle.style.top = `${y}px`;\n    particle.style.background = color;\n    particle.style.setProperty(\"--x\", `${Math.random() * 88 - 44}px`);\n    particle.style.setProperty(\"--y\", `${Math.random() * -86 - 8}px`);\n    $(\"#particleLayer\").appendChild(particle);\n    window.setTimeout(() => particle.remove(), 620);\n  }\n}\n\nfunction shake() {\n  $(\".play-column\").animate([\n    { transform: \"translateX(-4px)\" },\n    { transform: \"translateX(4px)\" },\n    { transform: \"translateX(0)\" }\n  ], { duration: 240 });\n}\n\nfunction tone(freq, duration = 0.1, volume = 0.045) {\n  if (!state.sound && volume > 0.02) return;\n  try {\n    audioCtx = audioCtx || new AudioContext();\n    const osc = audioCtx.createOscillator();\n    const gain = audioCtx.createGain();\n    osc.type = \"sine\";\n    osc.frequency.value = freq;\n    gain.gain.setValueAtTime(volume, audioCtx.currentTime);\n    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);\n    osc.connect(gain).connect(audioCtx.destination);\n    osc.start();\n    osc.stop(audioCtx.currentTime + duration);\n  } catch (error) {\n    console.warn(\"Tiny Factory Drop audio is unavailable.\", error);\n  }\n}\n\nfunction beep(freq, duration) {\n  if (state?.sound) tone(freq, duration);\n}\n\nfunction startMusic() {\n  window.clearInterval(musicTimer);\n  if (!state.music) return;\n  const notes = [262, 330, 392, 330, 294, 349, 440, 349];\n  let index = 0;\n  musicTimer = window.setInterval(() => {\n    if (state.music && !paused) tone(notes[index++ % notes.length], 0.18, 0.012);\n  }, 380);\n}\n\nfunction productSize() {\n  return $(\"#products\").clientWidth < 520 ? 51 : 58;\n}\n\nfunction distance(a, b) {\n  return Math.hypot(a.x - b.x, a.y - b.y);\n}\n\nfunction clamp(value, min, max) {\n  return Math.max(min, Math.min(max, value));\n}\n\nfunction formatNumber(value) {\n  return Math.floor(value).toLocaleString(\"en-US\");\n}\n\n$(\"#playBtn\").addEventListener(\"click\", startGame);\n$(\"#continueBtn\").addEventListener(\"click\", startGame);\n$(\"#dropBtn\").addEventListener(\"click\", () => dropItem(false));\n$(\"#claimOrderBtn\").addEventListener(\"click\", claimOrder);\n$(\"#upgradeList\").addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"[data-buy-upgrade]\");\n  if (button) buyUpgrade(button.dataset.buyUpgrade);\n});\n$(\"#machineList\").addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"[data-buy-machine]\");\n  if (button) buyMachine(button.dataset.buyMachine);\n});\n$(\"#modalContent\").addEventListener(\"click\", (event) => {\n  const tokenButton = event.target.closest(\"[data-buy-token]\");\n  if (tokenButton) buyTokenUpgrade(tokenButton.dataset.buyToken);\n  if (event.target.closest(\"[data-close-modal]\")) closeModal();\n});\n$(\"#helpBtn\").addEventListener(\"click\", openHelp);\n$(\"#orderInfoBtn\").addEventListener(\"click\", openHelp);\n$(\"#upgradeInfoBtn\").addEventListener(\"click\", openHelp);\n$(\"#settingsBtn\").addEventListener(\"click\", openSettings);\n$(\"#modalCloseBtn\").addEventListener(\"click\", closeModal);\n$(\"#prestigeBtn\").addEventListener(\"click\", openPrestige);\n$(\"#tokenShopBtn\").addEventListener(\"click\", openTokenShop);\n$(\"#pauseBtn\").addEventListener(\"click\", togglePause);\n$(\"#soundBtn\").addEventListener(\"click\", () => {\n  state.sound = !state.sound;\n  renderAudioButtons();\n  save();\n});\n$(\"#musicBtn\").addEventListener(\"click\", () => {\n  state.music = !state.music;\n  startMusic();\n  renderAudioButtons();\n  save();\n});\n$(\"#tutorialNextBtn\").addEventListener(\"click\", () => {\n  state.tutorial += 1;\n  showTutorial();\n});\n$(\"#tutorialSkipBtn\").addEventListener(\"click\", () => {\n  state.tutorialDone = true;\n  $(\"#tutorial\").classList.add(\"hidden\");\n  save();\n});\n\nwindow.addEventListener(\"beforeunload\", () => {\n  if (started) save();\n  window.clearInterval(saveTimer);\n  window.clearInterval(autoTimer);\n  window.clearInterval(musicTimer);\n});\n\nif (localStorage.getItem(SAVE_KEY)) {\n  $(\"#continueBtn\").classList.remove(\"hidden\");\n}\n\nwindow.tinyFactoryDebug = {\n  countProducts: () => items.length,\n  testDrop: () => dropItem(true)\n};\n"};

const contentTypes = {
  "index.html": "text/html; charset=utf-8",
  "styles.css": "text/css; charset=utf-8",
  "game.js": "text/javascript; charset=utf-8"
};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let path = decodeURIComponent(url.pathname);

    if (path === "/" || path === "") {
      path = "/index.html";
    }

    const key = path.replace(/^\//, "");
    const body = files[key];

    if (!body) {
      return new Response(files["index.html"], {
        headers: {
          "content-type": contentTypes["index.html"],
          "cache-control": "no-store"
        }
      });
    }

    return new Response(body, {
      headers: {
        "content-type": contentTypes[key] || "application/octet-stream",
        "cache-control": "no-store"
      }
    });
  }
};
